import{_ as e,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/troubleshooting.md","filePath":"es/guide/troubleshooting.md","lastUpdated":1793163976000}'),s={name:"es/guide/troubleshooting.md"};function l(n,a,t,c,p,d){return i(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><p>Esta página recopila problemas comunes de NueZip en macOS y cómo resolverlos.</p><h2 id="la-aplicacion-no-arranca-o-se-cierra-al-iniciar" tabindex="-1">La aplicación no arranca o se cierra al iniciar <a class="header-anchor" href="#la-aplicacion-no-arranca-o-se-cierra-al-iniciar" aria-label="Permalink to &quot;La aplicación no arranca o se cierra al iniciar&quot;">​</a></h2><p>Síntomas: NueZip no se abre, se cierra inmediatamente o muestra un error inesperado.</p><p>Pasos a probar:</p><ol><li>Asegúrate de que tu versión de macOS cumple los requisitos mínimos (macOS 14 Sonoma+).</li><li>Cierra y vuelve a abrir la app.</li><li>Reinicia tu Mac.</li><li>Si la app se descargó desde GitHub Releases, prueba a descargar la compilación más reciente o la versión notarizada.</li><li>Si persisten los problemas, recopila los registros (ver abajo) y abre un issue.</li></ol><h2 id="no-se-puede-abrir-un-archivo-rar" tabindex="-1">No se puede abrir un archivo RAR <a class="header-anchor" href="#no-se-puede-abrir-un-archivo-rar" aria-label="Permalink to &quot;No se puede abrir un archivo RAR&quot;">​</a></h2><p>Síntomas: NueZip falla al abrir un archivo <code>.rar</code>, o muestra un error.</p><p>Lista de comprobación:</p><ol><li>Asegúrate de que el archivo RAR no esté corrupto. Prueba a abrirlo con otra herramienta como The Unarchiver.</li><li>Los archivos RAR multi-volumen deben tener todas las partes presentes (<code>.part1.rar</code>, <code>.part2.rar</code>, etc.).</li><li>Los archivos RAR protegidos con contraseña requieren la contraseña correcta.</li><li>El formato RAR5 es compatible. Si tienes un formato RAR más antiguo, por favor repórtalo.</li></ol><h2 id="la-extraccion-falla-con-error-de-contrasena" tabindex="-1">La extracción falla con error de contraseña <a class="header-anchor" href="#la-extraccion-falla-con-error-de-contrasena" aria-label="Permalink to &quot;La extracción falla con error de contraseña&quot;">​</a></h2><p>Síntomas: La extracción falla con &quot;Contraseña incorrecta&quot; o error de descifrado.</p><p>Lista de comprobación:</p><ol><li>Verifica que la contraseña sea correcta — las contraseñas distinguen mayúsculas de minúsculas.</li><li>Asegúrate de que el tipo de cifrado admitido sea correcto (AES-256 para ZIP).</li><li>Prueba a volver a introducir la contraseña desde el gestor de contraseñas.</li></ol><h2 id="la-extension-de-finder-no-aparece" tabindex="-1">La extensión de Finder no aparece <a class="header-anchor" href="#la-extension-de-finder-no-aparece" aria-label="Permalink to &quot;La extensión de Finder no aparece&quot;">​</a></h2><p>Síntomas: Al hacer clic derecho en un archivo en Finder no aparecen opciones de NueZip.</p><p>Lista de comprobación:</p><ol><li>Habilita la extensión: Configuración del sistema → Privacidad y seguridad → Extensiones → Extensiones de Finder → Habilita <strong>NueZip</strong>.</li><li>Reinicia Finder: Haz clic derecho en Finder en Monitor de actividad → Relanzar, o ejecuta <code>killall Finder</code> en Terminal.</li><li>Reinstala la app si la extensión sigue sin aparecer.</li></ol><h2 id="licencia-compra-no-aparece" tabindex="-1">Licencia / compra no aparece <a class="header-anchor" href="#licencia-compra-no-aparece" aria-label="Permalink to &quot;Licencia / compra no aparece&quot;">​</a></h2><p>Síntomas: Compraste NueZip pero sigue mostrándose como versión de prueba.</p><p>Lista de comprobación:</p><ol><li>Asegúrate de haber iniciado sesión con el mismo Apple ID usado para la compra.</li><li>Restaura las compras: NueZip → Ajustes → Licencia → Restaurar compras.</li><li>Contacta con soporte si el problema persiste.</li></ol><h2 id="como-recopilar-registros-de-depuracion" tabindex="-1">Cómo recopilar registros de depuración <a class="header-anchor" href="#como-recopilar-registros-de-depuracion" aria-label="Permalink to &quot;Cómo recopilar registros de depuración&quot;">​</a></h2><p>Para ayudar a diagnosticar problemas, recopila los registros de depuración de NueZip:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copia los registros al Escritorio para compartirlos</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/NueZip-Logs</span></span></code></pre></div><p>Luego abre un issue en <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> y adjunta los registros.</p><h2 id="problemas-relacionados-con-permisos" tabindex="-1">Problemas relacionados con permisos <a class="header-anchor" href="#problemas-relacionados-con-permisos" aria-label="Permalink to &quot;Problemas relacionados con permisos&quot;">​</a></h2><p>Si una función solicita permiso pero no funciona tras concederlo:</p><ol><li>Cierra la app y vuélvela a abrir tras conceder el permiso.</li><li>Si es necesario, restablece el aviso de permiso con <code>tccutil</code> (consulta la <a href="./permissions.html">guía de permisos</a>).</li></ol><h2 id="problemas-de-rendimiento" tabindex="-1">Problemas de rendimiento <a class="header-anchor" href="#problemas-de-rendimiento" aria-label="Permalink to &quot;Problemas de rendimiento&quot;">​</a></h2><p>Si la app es lenta o no responde:</p><ol><li>Cierra otras aplicaciones pesadas.</li><li>Prueba a extraer un archivo más pequeño para aislar el problema.</li><li>Reinicia la app si el rendimiento empeora con el tiempo.</li></ol><h2 id="ver-registros" tabindex="-1">Ver registros <a class="header-anchor" href="#ver-registros" aria-label="Permalink to &quot;Ver registros&quot;">​</a></h2><p>Para solucionar cierres inesperados o problemas, los registros de la aplicación son el artefacto más útil. En compilaciones con sandbox (App Store), consulta:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span></span></code></pre></div><h2 id="restablecer-la-app" tabindex="-1">Restablecer la app <a class="header-anchor" href="#restablecer-la-app" aria-label="Permalink to &quot;Restablecer la app&quot;">​</a></h2><p>Para restablecer los ajustes y borrar los datos locales:</p><ol><li>Cierra NueZip</li><li>Elimina el contenedor (ten cuidado — esto borra todos los ajustes):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><ol start="3"><li>Vuelve a abrir NueZip y reconfigúralo.</li></ol><h2 id="informar-de-un-problema" tabindex="-1">Informar de un problema <a class="header-anchor" href="#informar-de-un-problema" aria-label="Permalink to &quot;Informar de un problema&quot;">​</a></h2><p>Al abrir un issue, incluye:</p><ul><li>Versión de macOS (Menú Apple → Acerca de este Mac)</li><li>Versión de NueZip (NueZip → Acerca de)</li><li>Pasos para reproducir</li><li>Registros (consulta la sección <a href="#ver-registros">Ver registros</a> para saber cómo recopilarlos)</li></ul><p>Esto ayuda a los encargados del mantenimiento a identificar y corregir el problema más rápido.</p>`,44)])])}const h=e(s,[["render",l]]);export{m as __pageData,h as default};
